#[summary("impossibility certificate")]
mod bmb_cert {
    spec fn never() -> bool { false }

    spec fn witness(n: u64) -> bool { n == 0 }

    #[effects(pure)]
    #[uses(witness, tasks::is_pred)]
    fn refute(n: u64) -> ()
        requires witness(n),
        ensures never(),
    {
        let r: u64 = tasks::pred(n);
    }

    #[effects(pure)]
    #[uses(witness)]
    fn reach() -> () {
        refute(0)
    }
}
